package glitch

import data.glitch_lib

# Helper to detect insecure URLs
is_insecure_url(str) {
    regex.match("(?i)^http://", str)
}

# Helper to detect disabled integrity (0, false, or "none"/"disabled")
is_integrity_disabled(value) {
    value.ir_type == "Integer"
    value.value == 0
} else {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    regex.match("(?i)^(none|disabled|no)$", value.value)
}

# Rule 1: Detect insecure protocols in URL-like attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"url", "source", "baseurl", "mirrorlist"}
    attr.value.ir_type == "String"
    is_insecure_url(attr.value.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Insecure HTTP protocol used for data transmission (CWE-353)"
    }
}

