is_insecure_url(val) {
    val.ir_type == "String"
    regex.match("(?i)^http://", val.value)
}

# Helper to check if a value disables integrity (0, false, "no", "none", "disabled")
is_integrity_disabled(val) {
    val.ir_type == "Integer"
    val.value == 0
} else {
    val.ir_type == "Boolean"
    val.value == false
} else {
    val.ir_type == "String"
    regex.match("(?i)^(no|none|disabled|false)$", val.value)
}

# Rule: Detect insecure URLs in various attributes (Ansible, Chef, Puppet)
